window.docContents[18].resolve({"/2___-Basic-notions-of-representation-theory/2___2___-Algebras/Section-2___2-heading-and-introduction-to-systematic-discussion/#Chapter2___Discussion_2___2_intro":{"contents":"\n\n\n\n","context":"Introduction to Representation Theory\u00092. Basic notions of representation theory\u00092.2. Algebras\u0009Section 2.2 heading and introduction to systematic discussion","header":"Section 2.2 heading and introduction to systematic discussion","id":"/2___-Basic-notions-of-representation-theory/2___2___-Algebras/Section-2___2-heading-and-introduction-to-systematic-discussion/#Chapter2___Discussion_2___2_intro"},"/2___-Basic-notions-of-representation-theory/2___3___-Representations/1-dimensional-representations-are-automatically-irreducible/#Introduction-to-Representation-Theory--2___-Basic-notions-of-representation-theory--2___3___-Representations--1-dimensional-representations-are-automatically-irreducible--1-dimensional-representations-are-automatically-irreducible--Formalization--Primary-declarations":{"contents":"A module of dimension one over the base field is simple for the given algebra action.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter2/Remark2.3.13; role=primary]\n\n","context":"Introduction to Representation Theory\u00092. Basic notions of representation theory\u00092.3. Representations\u00091-dimensional representations are automatically irreducible\u00091-dimensional representations are automatically irreducible\u0009Formalization","header":"Primary declarations","id":"/2___-Basic-notions-of-representation-theory/2___3___-Representations/1-dimensional-representations-are-automatically-irreducible/#Introduction-to-Representation-Theory--2___-Basic-notions-of-representation-theory--2___3___-Representations--1-dimensional-representations-are-automatically-irreducible--1-dimensional-representations-are-automatically-irreducible--Formalization--Primary-declarations"},"/2___-Basic-notions-of-representation-theory/2___5___-Quotients/#chapter-02___section-2-5":{"contents":"\n\n\n\n\n\n\n\n","context":"Introduction to Representation Theory\u00092. Basic notions of representation theory","header":"2.5. Quotients","id":"/2___-Basic-notions-of-representation-theory/2___5___-Quotients/#chapter-02___section-2-5"},"/4___-Representations-of-finite-groups___-Basic-results/4___12___-Problems/Decomposition-of-representations-of-A_5-on-icosahedron/#Chapter4___Problem4___12___5___formalization":{"contents":"\n\n\n\n","context":"Introduction to Representation Theory\u00094. Representations of finite groups: Basic results\u00094.12. Problems\u0009Decomposition of representations of A_5 on icosahedron\u0009Decomposition of representations of A_5 on icosahedron","header":"Formalization","id":"/4___-Representations-of-finite-groups___-Basic-results/4___12___-Problems/Decomposition-of-representations-of-A_5-on-icosahedron/#Chapter4___Problem4___12___5___formalization"},"/5___-Representations-of-finite-groups___-Further-results/5___11___-Examples/#chapter-05___section-5-11":{"contents":"\n\n\n\n\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results","header":"5.11. Examples","id":"/5___-Representations-of-finite-groups___-Further-results/5___11___-Examples/#chapter-05___section-5-11"},"/5___-Representations-of-finite-groups___-Further-results/5___21___-Schur-polynomials/Special-values-of-Schur-polynomials-at-geometric-progressions/#Chapter5___Proposition5___21___2":{"contents":"Proposition 5.21.2.\n\nS_\\lambda(1, z, z^2, \\ldots, z^{N-1}) = \\prod_{1 \\leq i < j \\leq N} \\frac{z^{\\lambda_i - i} - z^{\\lambda_j - j}}{z^{-i} - z^{-j}}.\n\nTherefore,\n\nS_\\lambda(1, \\ldots, 1) = \\prod_{1 \\leq i < j \\leq N} \\frac{\\lambda_i - \\lambda_j + j - i}{j - i}.\n\nProof. First, D_\\lambda(1, z, \\ldots, z^{N-1}) is a Vandermonde determinant evaluated at (z^{\\lambda_i + N - i})_{1 \\leq i \\leq N}, so it equals \\prod_{i < j} (z^{\\lambda_i + N - i} - z^{\\lambda_j + N - j}). Dividing by the same formula with \\lambda = 0 yields the formula for S_\\lambda(1, z, \\ldots, z^{N-1}). Now take \\lim_{z \\to 1} and apply L'Hopital's rule. \\square\n\n\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results\u00095.21. Schur polynomials\u0009Special values of Schur polynomials at geometric progressions","header":"Special values of Schur polynomials at geometric progressions","id":"/5___-Representations-of-finite-groups___-Further-results/5___21___-Schur-polynomials/Special-values-of-Schur-polynomials-at-geometric-progressions/#Chapter5___Proposition5___21___2"},"/5___-Representations-of-finite-groups___-Further-results/5___23___-Algebraic-representations-of-___GL_LPAR_V_RPAR____/Algebraic-_LPAR_rational___-polynomial_RPAR_-representation-of-GL_LPAR_V_RPAR_/#Chapter5___Definition5___23___1___formalization":{"contents":"\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results\u00095.23. Algebraic representations of $GL(V)$\u0009Algebraic (rational, polynomial) representation of GL(V)\u0009Algebraic (rational, polynomial) representation of GL(V)","header":"Formalization","id":"/5___-Representations-of-finite-groups___-Further-results/5___23___-Algebraic-representations-of-___GL_LPAR_V_RPAR____/Algebraic-_LPAR_rational___-polynomial_RPAR_-representation-of-GL_LPAR_V_RPAR_/#Chapter5___Definition5___23___1___formalization"},"/5___-Representations-of-finite-groups___-Further-results/5___2___-Algebraic-numbers-and-algebraic-integers/Algebraic-integers-form-a-ring_SEMI_-algebraic-numbers-form-a-field/#Chapter5___Proposition5___2___4":{"contents":"Proposition 5.2.4. (i) \\overline{\\mathbb{Z}} is a ring.\n\n(ii) \\overline{\\mathbb{Q}} is a field. Namely, it is an algebraic closure of the field of rational numbers.\n\nProof. We will be using Definition 5.2.2. Let \\alpha be an eigenvalue of\n\n\\mathcal{A} \\in \\mathrm{Mat}_n(\\mathbb{C})\n\nwith eigenvector v, and let \\beta be an eigenvalue of\n\n\\mathcal{B} \\in \\mathrm{Mat}_m(\\mathbb{C})\nwith eigenvector w. Then \\alpha \\pm \\beta is an eigenvalue of\n\n\\mathcal{A} \\otimes \\mathrm{Id}_m \\pm \\mathrm{Id}_n \\otimes \\mathcal{B},\n\nand \\alpha\\beta is an eigenvalue of\n\n\\mathcal{A} \\otimes \\mathcal{B}.\n\nThe corresponding eigenvector is in both cases v \\otimes w. This shows that both \\overline{\\mathbb{Z}} and \\overline{\\mathbb{Q}} are rings. To show that the latter is a field, it suffices to note that if \\alpha \\neq 0 is a root of a polynomial p(x) of degree d, then \\alpha^{-1} is a root of x^d p(1/x). The last statement is easy, since a number \\alpha is algebraic if and only if it defines a finite extension of \\mathbb{Q}. \\square\n\n\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results\u00095.2. Algebraic numbers and algebraic integers\u0009Algebraic integers form a ring; algebraic numbers form a field","header":"Algebraic integers form a ring; algebraic numbers form a field","id":"/5___-Representations-of-finite-groups___-Further-results/5___2___-Algebraic-numbers-and-algebraic-integers/Algebraic-integers-form-a-ring_SEMI_-algebraic-numbers-form-a-field/#Chapter5___Proposition5___2___4"},"/6___-Quiver-representations/6___6___-Reflection-functors/Section-6___6-heading___-Reflection-functors/#Chapter6___Section6___6_heading":{"contents":"\n\n","context":"Introduction to Representation Theory\u00096. Quiver representations\u00096.6. Reflection functors\u0009Section 6.6 heading: Reflection functors","header":"Section 6.6 heading: Reflection functors","id":"/6___-Quiver-representations/6___6___-Reflection-functors/Section-6___6-heading___-Reflection-functors/#Chapter6___Section6___6_heading"},"/6___-Quiver-representations/6___9___-Problems/Section-6___9-heading___-Problems/#Introduction-to-Representation-Theory--6___-Quiver-representations--6___9___-Problems--Section-6___9-heading___-Problems--Section-6___9-heading___-Problems--Formalization--Supporting-declarations":{"contents":"An auxiliary compatibility condition implies the associated property.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter6/Problem6.9.1; role=supporting]* Etingof et al., Introduction to Representation Theory [book-ref=Chapter6/Section6.9_heading; role=supporting]\n\nUnder the displayed ordering and finite-basis hypotheses, there is auxiliary data satisfying the two stated equalities.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter6/Problem6.9.3; role=supporting]* Etingof et al., Introduction to Representation Theory [book-ref=Chapter6/Section6.9_heading; role=supporting]\n\nThe eight-vector construction has the stated root-set, membership, matrix, and permuted\nadjacency properties.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter6/Problem6.9.2; role=supporting]* Etingof et al., Introduction to Representation Theory [book-ref=Chapter6/Section6.9_heading; role=supporting]\n\n","context":"Introduction to Representation Theory\u00096. Quiver representations\u00096.9. Problems\u0009Section 6.9 heading: Problems\u0009Section 6.9 heading: Problems\u0009Formalization","header":"Supporting declarations","id":"/6___-Quiver-representations/6___9___-Problems/Section-6___9-heading___-Problems/#Introduction-to-Representation-Theory--6___-Quiver-representations--6___9___-Problems--Section-6___9-heading___-Problems--Section-6___9-heading___-Problems--Formalization--Supporting-declarations"},"/7___-Introduction-to-categories/7___1___-The-definition-of-a-category/Examples-of-categories/#Chapter7___Example7___1___3___formalization":{"contents":"\n\n","context":"Introduction to Representation Theory\u00097. Introduction to categories\u00097.1. The definition of a category\u0009Examples of categories\u0009Examples of categories","header":"Formalization","id":"/7___-Introduction-to-categories/7___1___-The-definition-of-a-category/Examples-of-categories/#Chapter7___Example7___1___3___formalization"},"/7___-Introduction-to-categories/7___7___-Abelian-categories/Section-7___7___-Abelian-categories/#Chapter7___Introduction_7___7___formalization":{"contents":"\n\n","context":"Introduction to Representation Theory\u00097. Introduction to categories\u00097.7. Abelian categories\u0009Section 7.7: Abelian categories\u0009Section 7.7: Abelian categories","header":"Formalization","id":"/7___-Introduction-to-categories/7___7___-Abelian-categories/Section-7___7___-Abelian-categories/#Chapter7___Introduction_7___7___formalization"},"/9___-Structure-of-finite-dimensional-algebras/9___4___-Homological-dimension/Cartan-matrix-determinant-and-homological-dimension/#Introduction-to-Representation-Theory--9___-Structure-of-finite-dimensional-algebras--9___4___-Homological-dimension--Cartan-matrix-determinant-and-homological-dimension--Cartan-matrix-determinant-and-homological-dimension--Formalization--Supporting-declarations":{"contents":"An auxiliary statement whose displayed formal type is unavailable.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter9/Problem9.4.5; role=supporting]\n\n","context":"Introduction to Representation Theory\u00099. Structure of finite dimensional algebras\u00099.4. Homological dimension\u0009Cartan matrix determinant and homological dimension\u0009Cartan matrix determinant and homological dimension\u0009Formalization","header":"Supporting declarations","id":"/9___-Structure-of-finite-dimensional-algebras/9___4___-Homological-dimension/Cartan-matrix-determinant-and-homological-dimension/#Introduction-to-Representation-Theory--9___-Structure-of-finite-dimensional-algebras--9___4___-Homological-dimension--Cartan-matrix-determinant-and-homological-dimension--Cartan-matrix-determinant-and-homological-dimension--Formalization--Supporting-declarations"},"/9___-Structure-of-finite-dimensional-algebras/9___4___-Homological-dimension/Homological-dimension-of-a-ring/#Chapter9___Definition9___4___3":{"contents":"Definition 9.4.3. One says that a ring A has left (respectively, right) homological dimension \\leq d if every left (respectively, right) A-module M has projective dimension \\leq d. The homological dimension of A is exactly d if it is \\leq d but not \\leq d - 1. If such a d does not exist, one says that A has infinite homological dimension.\n\n\n\n","context":"Introduction to Representation Theory\u00099. Structure of finite dimensional algebras\u00099.4. Homological dimension\u0009Homological dimension of a ring","header":"Homological dimension of a ring","id":"/9___-Structure-of-finite-dimensional-algebras/9___4___-Homological-dimension/Homological-dimension-of-a-ring/#Chapter9___Definition9___4___3"},"/9___-Structure-of-finite-dimensional-algebras/9___4___-Homological-dimension/Projective-dimension/#Introduction-to-Representation-Theory--9___-Structure-of-finite-dimensional-algebras--9___4___-Homological-dimension--Projective-dimension--Projective-dimension--Formalization--Primary-declarations":{"contents":"The projective dimension of a module, valued in extended natural numbers.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter9/Definition9.4.1; role=primary]\n\n","context":"Introduction to Representation Theory\u00099. Structure of finite dimensional algebras\u00099.4. Homological dimension\u0009Projective dimension\u0009Projective dimension\u0009Formalization","header":"Primary declarations","id":"/9___-Structure-of-finite-dimensional-algebras/9___4___-Homological-dimension/Projective-dimension/#Introduction-to-Representation-Theory--9___-Structure-of-finite-dimensional-algebras--9___4___-Homological-dimension--Projective-dimension--Projective-dimension--Formalization--Primary-declarations"}});